setInterval(async () => {
  const updates = await fetch('/api/updates?since=' + lastSeen);
  if (updates.length) handle(updates);
}, 3000);   // 3s latency floor, and most calls return empty

async function longPoll() {
  const res = await fetch('/api/updates?since=' + lastSeen, { timeout: 30_000 });
  if (res.status === 200) handle(await res.json());
  longPoll();   // immediately reopen — this is the loop
}

