ws.send(JSON.stringify({ type: 'typing', conversationId }));

function backoff(attempt) {
  const base = Math.min(30_000, 1000 * 2 ** attempt);
  return base * (0.5 + Math.random());   // jitter spreads the reconnect wave
}
